    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        long d = (long) in.nval;
        long[] items = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            items[i] = (long) in.nval;
        }
        List<long[]> boxes = packBoxes(items, d);
        StringBuilder sb = new StringBuilder();
        sb.append(boxes.size()).append("\n");
        for (long[] b : boxes) sb.append(b[0]).append(" ").append(b[1]).append(" ").append(b[2]).append("\n");
        System.out.print(sb);
    }
}
